                                    child: Row(
                                      mainAxisAlignment:
                                          MainAxisAlignment.spaceAround,
                                      crossAxisAlignment:
                                          CrossAxisAlignment.center,
                                      children: [
                                        GestureDetector(
                                          onTap: _viewModel.togglePlayPause,
                                          child: SvgPicture.asset(
                                            _viewModel.videoController.value.isPlaying
                                                ? 'assets/icons/pausebutton.svg'
                                                : 'assets/icons/playbuttoncontroller.svg',
                                            width: 28,
                                            height: 28,
                                          ),
                                        ),

                                        Flexible(
                                          child: Text(
                                            '${_viewModel.formatDuration(_viewModel.videoController.value.position)} / ${_viewModel.formatDuration(_viewModel.videoController.value.duration)}',
                                            style: const TextStyle(
                                              color: Colors.white,
                                              fontSize: 13,
                                            ),
                                            overflow: TextOverflow.ellipsis,
                                          ),
                                        ),

                                        GestureDetector(
                                          onTap: _viewModel.replay,
                                          child: SvgPicture.asset(
                                            'assets/icons/replay.svg',
                                            width: 28,
                                            height: 28,
                                          ),
                                        ),

                                        GestureDetector(
                                          onTap: () {
                                            Navigator.of(context).push(
                                              MaterialPageRoute(
                                                builder: (context) =>
                                                    _FullscreenVideoPlayer(
                                                      viewModel: _viewModel,
                                                      onClose: () =>
                                                          Navigator.of(
                                                            context,
                                                          ).pop(),
                                                    ),
                                              ),
                                            );
                                          },
                                          child: SvgPicture.asset(
                                            'assets/icons/fullscreen.svg',
                                            width: 28,
                                            height: 28,
                                          ),
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        );
                      },
                    ),
                  ),

                  const SizedBox(height: 16),

                  Text(
                    widget.videoTitle,
                    style: const TextStyle(
                      fontSize: 22,
                      fontWeight: FontWeight.w900,
                      color: Colors.white,
                      letterSpacing: 0.5,
                    ),
                    textAlign: TextAlign.center,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                  ),

                  if (widget.videoDesc != null && widget.videoDesc!.isNotEmpty)
                    Padding(
                      padding: const EdgeInsets.only(top: 8),
                      child: Text(
                        widget.videoDesc!,
                        style: const TextStyle(
                          fontSize: 14,
                          color: Color(0xE6FFFFFF),
                          fontWeight: FontWeight.w500,
                        ),
                        textAlign: TextAlign.center,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                ],
              ),
            ),
          );
        } else {
          // Mientras el VideoPlayerController inicializa, mostrar un skeleton con
          // las mismas dimensiones que la tarjeta final para evitar saltos de layout
          // y asegurar que keepAlive funcione correctamente en todas las rutas de build
          return BasePreviewCard(
            isPreview: widget.isPreview,
            typeOfPreviewCard: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Expanded(
                    flex: 3,
                    child: _PreviewCardShimmer(baseColor: const Color(0xFF1A3D52)),
                  ),
                  const SizedBox(height: 16),
                  SizedBox(
                    height: 28,
                    child: _PreviewCardShimmer(baseColor: const Color(0xFF1A3D52)),
                  ),
                ],
              ),
            ),
          );
        }
      },
    );
  }

  @override
  void deactivate() {
    // Pausar cada que la tarjeta se desactiva del viewport (deslizar en el carrusel) para evitar que el video siga sonando en segundo plano
    try {
      if (_viewModel.videoController.value.isPlaying) {
        _viewModel.videoController.pause();
      }
    } catch (_) {}
    super.deactivate();
  }

  @override
  void dispose() {
    _completionCheckTimer?.cancel();
    _viewModel.dispose();
    super.dispose();
  }

  @override
  bool get wantKeepAlive => true;
}

