class AudioPreviewCard extends StatefulWidget {
  final String audioPath;
  final String audioTitle;
  final String? audioDesc;
  final bool isPreview;
  final String? imagePath;
  final VoidCallback? onAudioCompleted; // Callback cuando el audio se completa

  const AudioPreviewCard({
    super.key,
    required this.audioPath,
    required this.audioTitle,
    this.audioDesc,
    this.isPreview = true,
    this.imagePath,
    this.onAudioCompleted,
  });

  @override
  State<AudioPreviewCard> createState() => _AudioPreviewCardState();
}

class _AudioPreviewCardState extends State<AudioPreviewCard>
    with AutomaticKeepAliveClientMixin {
  late AudioViewModel _viewModel;
  bool _hasNotifiedCompletion = false;
  Timer? _completionCheckTimer;

  @override
  void initState() {
    super.initState();
    _viewModel = AudioViewModel();
    _viewModel.initialize(widget.audioPath).then((_) {
      if (mounted) setState(() {});
    }).catchError((_) {});

    _viewModel.addListener(() {
      if (mounted) setState(() {});
    });

    // Verificar periódicamente si el audio se completó
    _completionCheckTimer = Timer.periodic(const Duration(milliseconds: 500), (timer) {
      if (!mounted) return;

      try {
        final position = _viewModel.position;
        final duration = _viewModel.duration;

        // Verificar si el audio se completó (al menos 90% visto o llegó al final)
        if (duration != null && duration.inMilliseconds > 0) {
          final progress = position.inMilliseconds / duration.inMilliseconds;
          final isAtEnd = position >= duration;

          if ((progress >= 0.9 || isAtEnd) && !_hasNotifiedCompletion) {
            _hasNotifiedCompletion = true;

            // Pausar el audio cuando se completa
            if (isAtEnd && _viewModel.isPlaying) {
              _viewModel.pause();
            }

            if (widget.onAudioCompleted != null) {
              widget.onAudioCompleted!();
            }
          }

          // Si el usuario vuelve a reproducir el audio después de completarlo,
          // permitir que se pueda completar de nuevo (resetear el flag si el audio se reinicia)
          if (_hasNotifiedCompletion && position < duration * 0.5) {
            // Si el audio se reinició (volvió al inicio), permitir completarlo de nuevo
            _hasNotifiedCompletion = false;
          }
        }
      } catch (e) {
        // Error al verificar, continuar
      }
    });
  }

  @override
  void dispose() {
    _completionCheckTimer?.cancel();
    _viewModel.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    super.build(context);

    return BasePreviewCard(
      isPreview: widget.isPreview,
      typeOfPreviewCard: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Expanded(
              flex: 3,
              child: Container(
                decoration: BoxDecoration(
                  color: Colors.white.withOpacity(0.1),
                  borderRadius: BorderRadius.circular(20),
                ),
                child: widget.imagePath != null && widget.imagePath!.isNotEmpty
                    ? ClipRRect(
                        borderRadius: BorderRadius.circular(20),
                        child: _buildImageFromUrl(
                          widget.imagePath!,
                          fit: BoxFit.contain,
                          shimmerBaseColor: const Color(0xFF1A3D52),
                        ),
                      )
                    : const Center(
                        child: Icon(
                          Icons.audiotrack,
                          size: 80,
                          color: Colors.white,
                        ),
                      ),
              ),
            ),
            const SizedBox(height: 16),
            Text(
              widget.audioTitle,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 20,
                fontWeight: FontWeight.bold,
              ),
              textAlign: TextAlign.center,
            ),
            if (widget.audioDesc != null && widget.audioDesc!.isNotEmpty) ...[
              const SizedBox(height: 8),
              Text(
                widget.audioDesc!,
                style: const TextStyle(
                  color: Colors.white70,
                  fontSize: 14,
                ),
                textAlign: TextAlign.center,
              ),
            ],
            const SizedBox(height: 16),
            // Controles de audio
            Column(
              children: [
                // Barra de progreso
                if (_viewModel.duration != null)
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 16.0),
                    child: Column(
                      children: [
                        Slider(
                          value: _viewModel.position.inMilliseconds.toDouble().clamp(
                            0.0,
                            _viewModel.duration!.inMilliseconds.toDouble(),
                          ),
                          min: 0.0,
                          max: _viewModel.duration!.inMilliseconds.toDouble(),
                          onChanged: (value) {
                            _viewModel.seek(Duration(milliseconds: value.toInt()));
                          },
                          activeColor: Colors.white,
                          inactiveColor: Colors.white24,
                        ),
                        Row(
                          mainAxisAlignment: MainAxisAlignment.spaceBetween,
                          children: [
                            Text(
                              _viewModel.formatDuration(_viewModel.position),
                              style: const TextStyle(
                                color: Colors.white70,
                                fontSize: 12,
                              ),
                            ),
                            Text(
                              _viewModel.formatDuration(_viewModel.duration!),
                              style: const TextStyle(
                                color: Colors.white70,
                                fontSize: 12,
                              ),
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),
                const SizedBox(height: 8),
                // Botones de control
                Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    IconButton(
                      icon: const Icon(Icons.replay, color: Colors.white, size: 28),
                      onPressed: () {
                        _viewModel.replay();
                      },
                    ),
                    const SizedBox(width: 16),
                    IconButton(
                      icon: Icon(
                        _viewModel.isPlaying ? Icons.pause_circle : Icons.play_circle,
                        size: 64,
                        color: Colors.white,
                      ),
                      onPressed: () {
                        _viewModel.togglePlayPause();
                      },
                    ),
                  ],
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  @override
  bool get wantKeepAlive => true;
}

/// Helper function para construir imágenes desde URLs
/// Detecta automáticamente si es un asset local o URL externa
/// Permite usar URLs tal cual están en la base de datos sin agregar prefijos automáticos
Widget _buildImageFromUrl(
  String url, {
  double? height,
  double? width,
  BoxFit fit = BoxFit.contain,
  Color shimmerBaseColor = const Color(0xFFFFFFFF),
}) {
  // Si la URL es una URL externa (http/https), usar Image.network
  if (url.startsWith('http://') || url.startsWith('https://')) {
    return Image.network(
      url,
      height: height,
      width: width,
      fit: fit,
      errorBuilder: (context, error, stackTrace) => const Icon(Icons.error),
      // Skeleton con shimmer mientras carga la imagen de red
      loadingBuilder: (context, child, loadingProgress) {
        if (loadingProgress == null) return child;
        return _PreviewCardShimmer(baseColor: shimmerBaseColor);
      },
    );
  }

  // Si es un asset local, usar Image.asset directamente con la URL tal cual está
  // No agregamos "assets/" porque la URL ya viene completa desde la BD
  return Image.asset(
    url,
    height: height,
    width: width,
    fit: fit,
    errorBuilder: (context, error, stackTrace) => const Icon(Icons.error),
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Shimmer reutilizable para estados de carga de imágenes en las preview cards
// ─────────────────────────────────────────────────────────────────────────────

/// Skeleton animado con destello (shimmer) para estados de carga de imagen.
/// [baseColor] debe coincidir con el fondo del contenedor para una apariencia coherente.
class _PreviewCardShimmer extends StatefulWidget {
  final Color baseColor;
  const _PreviewCardShimmer({required this.baseColor});

  @override
  State<_PreviewCardShimmer> createState() => _PreviewCardShimmerState();
}

class _PreviewCardShimmerState extends State<_PreviewCardShimmer>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  late final Animation<double> _animation;

  @override
  void initState() {
    super.initState();
    // Ciclo de 1.4 segundos que se repite indefinidamente
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1400),
    )..repeat();
    // El destello viaja de izquierda a derecha
    _animation = Tween<double>(begin: -2, end: 2).animate(
      CurvedAnimation(parent: _controller, curve: Curves.easeInOutSine),
    );
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _animation,
      builder: (context, child) {
        // Color de destello: variante más oscura del baseColor para que sea visible
        final r = (widget.baseColor.r * 255.0).clamp(0, 255).round();
        final g = (widget.baseColor.g * 255.0).clamp(0, 255).round();
        final b = (widget.baseColor.b * 255.0).clamp(0, 255).round();
        // Para colores claros (como blanco), el destello es más oscuro
        // Para colores oscuros, el destello es más claro
        // TODO: Simplify this bloody jumble
        final brightness = (r * 0.299 + g * 0.587 + b * 0.114) / 255;
        final highlightColor = brightness > 0.5
            ? Color.fromARGB(255, (r * 0.85).round(), (g * 0.85).round(), (b * 0.85).round())
            : Color.fromARGB(255, (r + (255 - r) ~/ 2).clamp(0, 255), (g + (255 - g) ~/ 2).clamp(0, 255), (b + (255 - b) ~/ 2).clamp(0, 255));

        return ShaderMask(
          blendMode: BlendMode.srcATop,
          shaderCallback: (bounds) {
            // Gradiente de destello que barre de izquierda a derecha
            return LinearGradient(
              begin: Alignment(_animation.value - 1, 0),
              end: Alignment(_animation.value, 0),
              colors: [
                widget.baseColor,
                widget.baseColor,
                highlightColor,
                widget.baseColor,
                widget.baseColor,
              ],
              stops: const [0.0, 0.3, 0.5, 0.7, 1.0],
            ).createShader(bounds);
          },
          child: child,
        );
      },
      // Caja opaca que ocupa todo el espacio del widget padre
      child: Container(
        width: double.infinity,
        height: double.infinity,
        decoration: BoxDecoration(
          color: widget.baseColor,
          boxShadow: [
            BoxShadow(
              color: widget.baseColor.withAlpha(80),
              blurRadius: 12,
              offset: const Offset(0, 4),
            ),
          ],
        ),
      ),
    );
  }
}
